using System;using System.IO;using Amagadon;
class EditorTest {static void Main(string[] args) {string d=Path.Combine(Path.GetDirectoryName(typeof(EditorTest).Assembly.Location),"editor-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(d);string source=Path.Combine(d,"ACE.exe");File.Copy(args[0],source);string output=EditorPatch.Prepare(d);if(Core.Hash(source)!=EditorPatch.InputHash || Core.Hash(output)!="37ba22c6aa857d65588a2c6c7e7959e4c441196faaf8641bb3f3588cb3fcc51b")throw new Exception("hash mismatch");if(EditorPatch.Prepare(d)!=output)throw new Exception("reuse");File.WriteAllText(output,"foreign");bool rejected=false;try{EditorPatch.Prepare(d);}catch(IOException){rejected=true;}if(!rejected || File.ReadAllText(output)!="foreign")throw new Exception("overwrite protection");rejected=false;try{EditorPatch.Build(new byte[10]);}catch(IOException){rejected=true;}if(!rejected)throw new Exception("input guard");if(Diagnostics.StartInfo(output,d).EnvironmentVariables.ContainsKey("__COMPAT_LAYER"))throw new Exception("editor input profile");Console.WriteLine("PASS: embedded editor recipe, exact output, original preservation, repeat preparation, foreign output and unsupported input rejection");}}
